1	import { SignJWT, jwtVerify } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import { getSettingInt } from "./settings";
6	import type { User } from "@prisma/client";
7	
8	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
9	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
10	
11	export async function createSession(userId: string) {
12	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
13	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
14	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
15	  // Embed the account's current sessionVersion so a bump (password change/reset)
16	  // invalidates every previously-issued token. Missing => treated as 0.
17	  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
18	  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0 })
19	    .setProtectedHeader({ alg: "HS256" })
20	    .setIssuedAt()
21	    .setExpirationTime(`${days}d`)
22	    .sign(secret);
23	  const jar = await cookies();
24	  const secure = process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1";
25	  jar.set(COOKIE, token, {
26	    httpOnly: true,
27	    sameSite: "lax",
28	    secure,
29	    maxAge: 60 * 60 * 24 * days,
30	    path: "/",
31	  });
32	  // Non-sensitive, JS-readable flag so the (static) marketing header can show
33	  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
34	  // no identity — just presence. Always cleared alongside the session cookie.
35	  jar.set("nxeon_authed", "1", {
36	    httpOnly: false,
37	    sameSite: "lax",
38	    secure,
39	    maxAge: 60 * 60 * 24 * days,
40	    path: "/",
41	  });
42	}
43	
44	export async function destroySession() {
45	  const jar = await cookies();
46	  jar.delete(COOKIE);
47	  jar.delete("nxeon_authed");
48	}
49	
50	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
51	
52	/** The real signed-in account, ignoring any impersonation. */
53	export const realUser = cache(async (): Promise<User | null> => {
54	  const jar = await cookies();
55	  const token = jar.get(COOKIE)?.value;
56	  if (!token) return null;
57	  try {
58	    const { payload } = await jwtVerify(token, secret);
59	    if (!payload.sub) return null;
60	    const user = await db.user.findUnique({ where: { id: payload.sub } });
61	    if (!user || user.suspended) return null;
62	    // Session revocation: a token is only valid while its embedded version matches
63	    // the account's current sessionVersion. Older tokens without `sv` count as 0,
64	    // so accounts that never bumped stay logged in (backward-compatible).
65	    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
66	    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
67	    return user;
68	  } catch {
69	    return null;
70	  }
71	});
72	
73	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
74	export const currentUser = cache(async (): Promise<User | null> => {
75	  const real = await realUser();
76	  if (!real) return null;
77	  if (real.role === "ADMIN") {
78	    const jar = await cookies();
79	    const imp = jar.get(IMP_COOKIE)?.value;
80	    if (imp) {
81	      try {
82	        const { payload } = await jwtVerify(imp, secret);
83	        if (payload.adminId === real.id && typeof payload.sub === "string") {
84	          const target = await db.user.findUnique({ where: { id: payload.sub } });
85	          if (target) return target;
86	        }
87	      } catch {
88	        /* expired/invalid impersonation — fall through to real user */
89	      }
90	    }
91	  }
92	  return real;
93	});
94	
95	/** Non-null when the current request is an admin impersonating a customer. */
96	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
97	  const real = await realUser();
98	  if (!real || real.role !== "ADMIN") return null;
99	  const target = await currentUser();
100	  if (!target || target.id === real.id) return null;
101	  return { admin: real, target };
102	});
103	
104	export async function setImpersonation(targetUserId: string) {
105	  const real = await realUser();
106	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
107	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
108	    .setProtectedHeader({ alg: "HS256" })
109	    .setIssuedAt()
110	    .setExpirationTime("2h")
111	    .sign(secret);
112	  const jar = await cookies();
113	  jar.set(IMP_COOKIE, token, {
114	    httpOnly: true,
115	    sameSite: "lax",
116	    secure: process.env.NODE_ENV === "production",
117	    path: "/",
118	    maxAge: 7200,
119	  });
120	}
121	
122	export async function clearImpersonation() {
123	  const jar = await cookies();
124	  jar.delete(IMP_COOKIE);
125	}
126	
127	/**
128	 * Guard for wallet-debit / paid actions: refuse to run while an admin is
129	 * impersonating a customer. Keeps money movements attributable to the account
130	 * holder and prevents an admin from spending a customer's balance on their behalf.
131	 * Throws a friendly, user-facing error. Call at the top of every spend path.
132	 */
133	export async function assertNotImpersonating(): Promise<void> {
134	  const imp = await impersonating();
135	  if (imp) {
136	    throw new Error(
137	      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
138	    );
139	  }
140	}
141	
142	export async function requireUser(): Promise<User> {
143	  const user = await currentUser();
144	  if (!user) throw new Error("UNAUTHORIZED");
145	  return user;
146	}
147	
148	export async function requireAdmin(): Promise<User> {
149	  const user = await requireUser();
150	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
151	  return user;
152	}
153	
154	/**
155	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
156	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
157	 * per-area gating lives in lib/rbac.ts (`requireArea`).
158	 */
159	export async function requireStaff(): Promise<User> {
160	  const user = await realUser();
161	  if (!user) throw new Error("UNAUTHORIZED");
162	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
163	    throw new Error("FORBIDDEN");
164	  }
165	  return user;
166	}
