52	/** Template keys whose emails ship the itemised invoice as an attachment. */
53	const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);
54	
55	export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };
56	
57	/**
58	 * Build the invoice attachment for an email. There is no PDF library installed
59	 * (and we can't add dependencies), so we attach the branded, print-ready
60	 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
61	 * browser's Print → Save as PDF, matching the on-site download route.
62	 */
63	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
64	  try {
65	    const invoice = await db.invoice.findUnique({
66	      where: { id: invoiceId },
67	      include: { user: { select: { name: true, email: true } } },
68	    });
69	    if (!invoice) return null;
70	    const html = renderInvoiceHTML(invoice, invoice.user);
71	    const number = String(invoice.number).padStart(5, "0");
72	    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
73	  } catch (e) {
74	    console.error("[mailer] failed to build invoice attachment:", e);
75	    return null;
76	  }
77	}
78	
79	export type SendMailOpts = {
80	  to: string;
81	  /** Explicit subject. Optional when `template` is provided. */
82	  subject?: string;
83	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
84	  html?: string;
85	  text?: string;
86	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
87	  template?: string;
88	  /** Variables for `{{placeholders}}` when rendering from a template. */
89	  vars?: Record<string, unknown>;
90	  /** Attribution for the EmailLog row. */
91	  userId?: string | null;
92	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
93	  invoiceId?: string;
94	  /** Extra attachments. */
95	  attachments?: MailAttachment[];
96	};
97	
98	/**
99	 * Send an email. Never throws — logs and returns false on failure so callers
100	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
101	 * FAILED + error otherwise) for the admin Logs viewer.
102	 */
103	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
104	  // Resolve subject/html: prefer explicit values, otherwise render the template.
105	  let subject = opts.subject ?? "";
106	  let html = opts.html ?? "";
107	  const templateKey = opts.template ?? null;
108	
109	  if (templateKey && !opts.html) {
110	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
111	    subject = opts.subject ?? rendered.subject;
112	    html = rendered.html;
113	  }
114	
115	  // Assemble attachments (invoice auto-attaches for the relevant templates).
116	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
117	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
118	  if (wantInvoice && opts.invoiceId) {
119	    const att = await invoiceAttachment(opts.invoiceId);
120	    if (att) attachments.push(att);
121	  }
122	
123	  try {
124	    const c = await loadSmtp();
125	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
126	      console.warn("[mailer] not configured — skipping email:", subject);
127	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
128	      return false;
129	    }
130	    const t = transport(c);
131	    await t.sendMail({
132	      from: c.from,
133	      to: opts.to,
134	      subject,
135	      html,
136	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
137	      attachments: attachments.length ? attachments : undefined,
138	    });
139	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
140	    return true;
141	  } catch (e) {
142	    console.error("[mailer] send failed:", e);
143	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
144	    return false;
145	  }
146	}
147	
148	/**
149	 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
150	 * and (for billing templates) attach the invoice. Thin convenience over
151	 * `sendMail` for new callers.
152	 */
153	export async function sendTemplate(
154	  key: string,
155	  to: string,
156	  vars: Record<string, unknown> = {},
157	  opts: { userId?: string | null; invoiceId?: string; attachments?: MailAttachment[] } = {},
158	): Promise<boolean> {
159	  return sendMail({ to, template: key, vars, userId: opts.userId, invoiceId: opts.invoiceId, attachments: opts.attachments });
160	}
161	
162	export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
163	  try {
164	    const c = await loadSmtp();
165	    const t = transport(c);
166	    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
167	    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
168	    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
169	    return { ok: true };
170	  } catch (e: any) {
171	    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
172	  }
173	}
174	
175	const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
176	
177	/**
178	 * Shared responsive email shell (inline styles for client compatibility).
179	 * Kept for the synchronous, code-rendered `emails.*` templates below and any
180	 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
181	 */
182	export function layout(title: string, body: string): string {
183	  // Delegate to the shared premium shell so every email is consistent.
184	  const heading = title
185	    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
186	    : "";
187	  return wrapEmail(`${heading}<div>${body}</div>`);
188	}
189	
190	export function button(href: string, label: string): string {
191	  return emailButton(href, label);
192	}
193	
194	// ---- Transactional templates (synchronous, code-rendered fallbacks) ----
195	//
196	// These preserve the existing public API for callers that destructure
197	// `{ subject, html }` synchronously. Each also carries a `template` field
198	// mapping it onto its DB template key, so the (unowned) call sites can be
199	// migrated to `sendMail({ template, vars })` later without renaming anything.
200	
201	const appUrl = () => renderAppUrl();
202	
203	export const emails = {
204	  welcome: (name: string) => ({
205	    template: "welcome",
206	    subject: "Welcome to Nxeon",
207	    html: layout(
208	      `Welcome, ${name}!`,
209	      `<p>Your Nxeon account is ready. Deploy your first NVMe VPS in under two minutes — pick a plan, choose an OS or one-click app, and you're live.</p>${button(`${appUrl()}/dashboard/deploy`, "Deploy a server")}`
210	    ),
211	  }),
212	  provisioned: (hostname: string, ssh: string) => ({
213	    template: "server_provisioned",
214	    subject: `Your server ${hostname} is ready`,
215	    html: layout(
216	      `${hostname} is live`,
217	      `<p>Your server has been provisioned and is running.</p><p style="font-family:monospace;background:#0a101f;padding:10px;border-radius:8px">${ssh}</p>${button(`${appUrl()}/dashboard/servers`, "Manage server")}`
218	    ),
219	  }),
220	  receipt: (amount: string, desc: string) => ({
221	    template: "receipt",
222	    subject: `Payment received — ${amount}`,
223	    html: layout("Payment received", `<p>We've received your payment of <b>${amount}</b> for ${desc}. Thank you!</p>${button(`${appUrl()}/dashboard/invoices`, "View invoices")}`),
224	  }),
225	  renewalWarning: (hostname: string, date: string) => ({
226	    template: "renewal_reminder",
227	    subject: `${hostname} renews soon`,
228	    html: layout("Renewal reminder", `<p>Your server <b>${hostname}</b> renews on ${date}. Make sure your wallet has enough balance to avoid suspension.</p>${button(`${appUrl()}/dashboard/billing`, "Top up wallet")}`),
229	  }),
230	  suspended: (hostname: string) => ({
231	    template: "server_suspended",
232	    subject: `${hostname} suspended — payment overdue`,
233	    html: layout("Server suspended", `<p><b>${hostname}</b> was suspended for non-payment. Pay from your dashboard to restore access instantly.</p>${button(`${appUrl()}/dashboard/billing`, "Restore access")}`),
234	  }),
235	  passwordReset: (link: string) => ({
236	    template: "password_reset",
237	    subject: "Reset your Nxeon password",
238	    html: layout("Reset your password", `<p>Someone requested a password reset for your account. This link expires in 1 hour. If this wasn't you, ignore this email.</p>${button(link, "Reset password")}<p style="font-size:12px;color:#64748b">Or paste this URL: ${link}</p>`),
239	  }),
240	};
241	
242	// Re-exported so other modules can build DB-templated bodies consistently.
243	export { wrapEmail, emailButton };
