// HTML sanitisation + text-preview helpers for the native webmail client.
//
// This is a plain server-side module (no "use server"): it is imported by the
// IMAP engine and the mail server actions to sanitise message bodies before
// they ever reach the client. `safeHtml` is DEFENCE IN DEPTH — the UI additionally
// renders the returned markup inside a sandboxed <iframe> — but we still strip the
// obvious script/exfiltration vectors here so a raw body never ships un-neutered.

const DANGEROUS_WITH_CONTENT = /<(script|style|iframe|object|embed|noscript|template|frameset|frame|applet)\b[\s\S]*?<\/\1\s*>/gi;
const DANGEROUS_STANDALONE =
  /<\/?(script|style|iframe|object|embed|noscript|template|frameset|frame|applet|link|meta|base|form)\b[^>]*>/gi;

// Attributes whose value can carry a navigable/loadable URL.
const URL_ATTRS = "href|src|xlink:href|action|formaction|background|poster|data|srcset";
// Schemes we never allow in those attributes.
const BAD_SCHEME = /^\s*(?:javascript|vbscript|data|blob|file)\s*:/i;

/**
 * Sanitise an untrusted HTML email body. Removes:
 *  - <script>/<style>/<iframe>/<object>/<embed> (and similar) elements + content
 *  - inline event handlers (on*=…)
 *  - javascript:/vbscript:/data:/blob:/file: URLs in link/src-style attributes
 * Returns "" for null/empty input. Never throws.
 */
export function safeHtml(html: string | null | undefined): string {
  if (!html) return "";
  let out = String(html);

  // 1) Drop dangerous elements together with their contents (handles nested too
  // because the pattern is non-greedy and re-run until stable).
  let prev: string;
  do {
    prev = out;
    out = out.replace(DANGEROUS_WITH_CONTENT, "");
  } while (out !== prev);

  // 2) Remove any leftover standalone dangerous / layout-breaking tags.
  out = out.replace(DANGEROUS_STANDALONE, "");

  // 3) Strip inline event handlers in all quoting styles.
  out = out.replace(/\son[a-z0-9_-]+\s*=\s*"[^"]*"/gi, "");
  out = out.replace(/\son[a-z0-9_-]+\s*=\s*'[^']*'/gi, "");
  out = out.replace(/\son[a-z0-9_-]+\s*=\s*[^\s>]+/gi, "");

  // 4) Neutralise dangerous URL schemes in navigable/loadable attributes.
  const attr = new RegExp(`\\s(${URL_ATTRS})\\s*=\\s*("([^"]*)"|'([^']*)'|([^\\s>]+))`, "gi");
  out = out.replace(attr, (match, name: string, _all: string, dq?: string, sq?: string, uq?: string) => {
    const value = dq ?? sq ?? uq ?? "";
    if (BAD_SCHEME.test(decodeAttr(value))) return ` ${name}="#"`;
    return match;
  });

  return out;
}

// Decode the handful of entity/whitespace tricks used to smuggle "javascript:"
// past a naive scheme check (e.g. "java&#115;cript:", "java\tscript:").
function decodeAttr(v: string): string {
  return v
    .replace(/&#x([0-9a-f]+);?/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);?/g, (_, d) => safeFromCodePoint(parseInt(d, 10)))
    .replace(/[\s�-]+/g, "");
}

function safeFromCodePoint(code: number): string {
  if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return "";
  try {
    return String.fromCodePoint(code);
  } catch {
    return "";
  }
}

const ENTITIES: Record<string, string> = {
  "&nbsp;": " ",
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&apos;": "'",
  "&mdash;": "—",
  "&ndash;": "–",
  "&hellip;": "…",
};

function decodeEntities(text: string): string {
  return text
    .replace(/&(?:nbsp|amp|lt|gt|quot|#39|apos|mdash|ndash|hellip);/g, (m) => ENTITIES[m] ?? m)
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => safeFromCodePoint(parseInt(d, 10)));
}

/**
 * Produce a compact (~140-char) plaintext snippet from an HTML or plaintext
 * body, suitable for a message-list preview. Strips markup, collapses
 * whitespace, decodes common entities, and adds an ellipsis when truncated.
 */
export function previewText(source: string | null | undefined, max = 140): string {
  if (!source) return "";
  let text = String(source);
  // Remove script/style blocks with their content so we never leak CSS/JS text.
  text = text.replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, " ");
  // Turn block boundaries into spaces, then strip remaining tags.
  text = text.replace(/<(?:br|\/p|\/div|\/tr|\/li|\/h[1-6])\b[^>]*>/gi, " ");
  text = text.replace(/<[^>]+>/g, " ");
  text = decodeEntities(text);
  text = text.replace(/\s+/g, " ").trim();
  if (text.length <= max) return text;
  return text.slice(0, max).replace(/\s+\S*$/, "").trimEnd() + "…";
}

// IMAP engine for the native webmail client.
//
// Plain server-side module (NOT "use server"): it holds the short-lived imapflow
// connection helpers, special-use → role mapping, and the mailbox-ownership
// resolver shared by the server actions (lib/actions-mail.ts) and the attachment
// download route (app/api/mail/attachment/route.ts). Every connection is opened
// per-request and always closed. It is never imported into a client bundle.

import { ImapFlow } from "imapflow";
import type {
  FetchMessageObject,
  MailboxLockOptions,
  MessageAddressObject,
  MessageStructureObject,
} from "imapflow";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { MAIL_IMAP_HOST, MAIL_IMAP_PORT, type MailAddress, type MailFolderRole } from "./types";
import type { User } from "@prisma/client";

// mailparser ships no bundled types; declare the slice we use (ambient, so it is
// available to any other file that imports the package too).
declare module "mailparser" {
  export interface ParsedAddress {
    name?: string;
    address?: string;
  }
  export interface AddressObject {
    value: ParsedAddress[];
    text: string;
    html?: string;
  }
  export interface Attachment {
    type: "attachment";
    partId?: string;
    filename?: string;
    contentType: string;
    contentDisposition?: string;
    size: number;
    content: Buffer;
    cid?: string;
    contentId?: string;
    related?: boolean;
  }
  export interface ParsedMail {
    subject?: string;
    from?: AddressObject;
    to?: AddressObject | AddressObject[];
    cc?: AddressObject | AddressObject[];
    bcc?: AddressObject | AddressObject[];
    date?: Date;
    messageId?: string;
    inReplyTo?: string;
    references?: string | string[];
    html?: string | false;
    text?: string;
    textAsHtml?: string;
    attachments: Attachment[];
  }
  export function simpleParser(source: Buffer | string, options?: Record<string, unknown>): Promise<ParsedMail>;
}

/** The TLS servername the mail server's certificate is issued for. */
export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";

/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
export type MailboxCredentials = { address: string; password: string };

/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
export type ResolvedMailbox = {
  user: User;
  mailboxId: string;
  address: string;
  quotaMB: number | null;
  cred: MailboxCredentials;
};

/**
 * Resolve the mailbox a request may act on. Requires an authenticated user,
 * loads only mailboxes belonging to that user's email subscriptions, and (when
 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
 * credential; throws a friendly error if the password was never captured.
 *
 * NEVER returns a mailbox the caller does not own.
 */
export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
  const user = await requireUser();
  const boxes = await db.mailbox.findMany({
    where: { subscription: { userId: user.id } },
    include: { subscription: true },
    orderBy: { createdAt: "asc" },
  });
  if (boxes.length === 0) {
    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
  }

  let box = boxes[0];
  if (mailboxAddress) {
    const wanted = mailboxAddress.trim().toLowerCase();
    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
    if (!match) throw new Error("You do not have access to that mailbox.");
    box = match;
  }

  const password = decryptSecret(box.passwordEnc);
  if (!password) {
    throw new Error("Please reset your mailbox password first to enable webmail access.");
  }

  return {
    user,
    mailboxId: box.id,
    address: box.address,
    quotaMB: box.quotaMB ?? null,
    cred: { address: box.address, password },
  };
}

/** Build a per-request imapflow client for the given credential. */
export function createImapClient(cred: MailboxCredentials): ImapFlow {
  return new ImapFlow({
    host: MAIL_IMAP_HOST,
    port: MAIL_IMAP_PORT,
    secure: true,
    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
    // and validation servername so TLS verifies against the right name.
    servername: MAIL_TLS_SERVERNAME,
    tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
    auth: { user: cred.address, pass: cred.password },
    logger: false,
    disableAutoIdle: true,
  });
}

/**
 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
 * logout, falling back to a hard close). Suitable for one operation per request.
 */
export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
  const client = createImapClient(cred);
  await client.connect();
  try {
    return await fn(client);
  } finally {
    try {
      await client.logout();
    } catch {
      try {
        client.close();
      } catch {
        /* already gone */
      }
    }
  }
}

/**
 * Like `withImap` but also selects `path` under a mailbox lock (released before
 * the connection closes). Use for any op that fetches/searches/mutates messages.
 */
export async function withMailbox<T>(
  cred: MailboxCredentials,
  path: string,
  fn: (client: ImapFlow) => Promise<T>,
  opts?: { readOnly?: boolean },
): Promise<T> {
  return withImap(cred, async (client) => {
    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
    const lock = await client.getMailboxLock(path, lockOpts);
    try {
      return await fn(client);
    } finally {
      lock.release();
    }
  });
}

/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
export function folderRole(path: string, specialUse?: string): MailFolderRole {
  const su = (specialUse || "").toLowerCase();
  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
  switch (su) {
    case "\\sent":
      return "sent";
    case "\\drafts":
      return "drafts";
    case "\\trash":
      return "trash";
    case "\\junk":
      return "junk";
    case "\\archive":
    case "\\all":
      return "archive";
  }
  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
  if (leaf === "inbox") return "inbox";
  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
  if (["drafts", "draft"].includes(leaf)) return "drafts";
  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
  return "custom";
}

/** Convert an imapflow envelope address to our MailAddress shape. */
export function toMailAddress(a: MessageAddressObject | undefined): MailAddress {
  return { name: a?.name || undefined, address: a?.address || "" };
}

/** Convert an array of imapflow envelope addresses to MailAddress[]. */
export function toMailAddresses(list: MessageAddressObject[] | undefined): MailAddress[] {
  return (list || []).map(toMailAddress).filter((a) => a.address);
}

/**
 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
 * "1" for a simple single-part message (whose structure carries no part id).
 */
export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
  if (!structure) return { part: "1", isHtml: false };
  const leaves: MessageStructureObject[] = [];
  const walk = (node: MessageStructureObject) => {
    if (node.childNodes && node.childNodes.length) {
      node.childNodes.forEach(walk);
    } else {
      leaves.push(node);
    }
  };
  walk(structure);

  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
  if (plain) return { part: plain.part || "1", isHtml: false };
  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
  if (html) return { part: html.part || "1", isHtml: true };
  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
}

/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
  if (!structure) return false;
  let found = false;
  const walk = (node: MessageStructureObject) => {
    const type = (node.type || "").toLowerCase();
    const disp = (node.disposition || "").toLowerCase();
    if (node.childNodes && node.childNodes.length) {
      node.childNodes.forEach(walk);
      return;
    }
    if (disp === "attachment") found = true;
    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
  };
  walk(structure);
  return found;
}

/** Read imapflow message flags into the summary booleans. */
export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
  const f = flags ?? new Set<string>();
  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
}

/** Best-effort ISO date string from an imapflow fetch result. */
export function isoDate(msg: Pick<FetchMessageObject, "envelope" | "internalDate">): string {
  const d = msg.envelope?.date || (msg.internalDate ? new Date(msg.internalDate) : undefined);
  const date = d instanceof Date ? d : d ? new Date(d) : new Date(0);
  return Number.isNaN(date.getTime()) ? new Date(0).toISOString() : date.toISOString();
}

"use server";

// Server actions for the native Nxeon webmail client (/dashboard/mail).
//
// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
// talks to the self-hosted mail server over IMAP/SMTP. Mutating actions are
// rate-limited. Bodies are sanitised (`safeHtml`) before leaving the server.
//
// Signatures are fixed by lib/mail/types.ts — the UI builds against the same
// contract, so do not change them here.

import nodemailer from "nodemailer";
import { simpleParser } from "mailparser";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
import {
  MAIL_SMTP_HOST,
  MAIL_SMTP_PORT,
  type ListResult,
  type MailboxInfo,
  type MailFolder,
  type MessageFull,
  type MessageSummary,
  type SendPayload,
} from "@/lib/mail/types";
import {
  MAIL_TLS_SERVERNAME,
  findPreviewPart,
  folderRole,
  isoDate,
  readFlags,
  resolveMailbox,
  structureHasAttachments,
  toMailAddress,
  toMailAddresses,
  withImap,
  withMailbox,
  type MailboxCredentials,
} from "@/lib/mail/imap";
import { previewText, safeHtml } from "@/lib/mail/render";
import type { ImapFlow } from "imapflow";

const PAGE_SIZE = 50;

/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
function enforceRateLimit(key: string, opts: RateLimitOptions) {
  const r = checkRateLimit(key, opts);
  if (!r.ok) {
    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
  }
}

// ---------------------------------------------------------------------------
// Mailboxes
// ---------------------------------------------------------------------------

/** The signed-in user's mailboxes with used/quota bytes (best effort per box). */
export async function getMailboxes(): Promise<MailboxInfo[]> {
  const user = await requireUser();
  const boxes = await db.mailbox.findMany({
    where: { subscription: { userId: user.id } },
    include: { subscription: true },
    orderBy: { createdAt: "asc" },
  });

  const out: MailboxInfo[] = [];
  for (const box of boxes) {
    const quotaBytes = box.quotaMB ? box.quotaMB * 1024 * 1024 : 0;
    const password = decryptSecret(box.passwordEnc);
    let usedBytes = 0;
    let liveQuota = quotaBytes;
    if (password) {
      try {
        const q = await withImap({ address: box.address, password }, async (client) => {
          const quota = await client.getQuota().catch(() => false as const);
          if (quota && quota.storage) return quota.storage;
          // Fall back to STATUS SIZE on INBOX where QUOTA isn't advertised.
          const st = await client.status("INBOX", { size: true }).catch(() => null);
          return st?.size != null ? { used: st.size, limit: quotaBytes } : null;
        });
        if (q) {
          usedBytes = q.used ?? 0;
          if (q.limit && q.limit > 0) liveQuota = q.limit;
        }
      } catch {
        /* connection/auth issue — report zero usage rather than failing the page */
      }
    }
    out.push({ address: box.address, usedBytes, quotaBytes: liveQuota });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Folders
// ---------------------------------------------------------------------------

/** List the mailbox's folders with unread/total counts and their role. */
export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
  const { cred } = await resolveMailbox(mailboxAddress);
  return withImap(cred, async (client) => {
    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
    const folders: MailFolder[] = [];
    for (const f of list) {
      // Skip containers that can't hold messages.
      if (f.flags?.has("\\Noselect")) continue;
      folders.push({
        path: f.path,
        name: f.name || f.path,
        role: folderRole(f.path, f.specialUse),
        unread: f.status?.unseen ?? 0,
        total: f.status?.messages ?? 0,
      });
    }
    // Stable, useful ordering: known roles first, then custom alphabetically.
    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
    return folders;
  });
}

// ---------------------------------------------------------------------------
// Message list
// ---------------------------------------------------------------------------

/** Decode a downloaded body part (transfer-encoding already decoded by server). */
function decodeCharset(buf: Buffer, charset?: string): string {
  const cs = (charset || "").toLowerCase();
  if (/latin1|8859|1252/.test(cs)) return buf.toString("latin1");
  return buf.toString("utf8");
}

/** Fetch a short, transfer-decoded snippet of a message's text part for preview. */
async function fetchPreview(client: ImapFlow, uid: number, part: string): Promise<string> {
  try {
    const { meta, content } = await client.download(String(uid), part, { uid: true, maxBytes: 4096 });
    const chunks: Buffer[] = [];
    for await (const chunk of content) chunks.push(chunk as Buffer);
    return previewText(decodeCharset(Buffer.concat(chunks), meta.charset));
  } catch {
    return "";
  }
}

/**
 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
 * subject / from / to / body. Envelopes + a light body snippet only — never the
 * full body — so lists stay cheap.
 */
export async function listMessages(
  folder: string,
  page: number,
  search?: string,
  mailboxAddress?: string,
): Promise<ListResult> {
  const { cred } = await resolveMailbox(mailboxAddress);
  const pageNum = Math.max(1, Math.floor(page) || 1);

  return withMailbox(
    cred,
    folder,
    async (client) => {
      const term = search?.trim();
      const query = term
        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
        : { all: true };
      const found = await client.search(query, { uid: true });
      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first

      const total = uids.length;
      const start = (pageNum - 1) * PAGE_SIZE;
      const pageUids = uids.slice(start, start + PAGE_SIZE);
      if (pageUids.length === 0) {
        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
      }

      // 1) Cheap metadata pass for the page.
      const metaByUid = new Map<number, MessageSummary>();
      const previewPartByUid = new Map<number, string>();
      for await (const msg of client.fetch(
        pageUids,
        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
        { uid: true },
      )) {
        const flags = readFlags(msg.flags);
        const env = msg.envelope;
        metaByUid.set(msg.uid, {
          uid: msg.uid,
          folder,
          from: toMailAddress(env?.from?.[0]),
          to: toMailAddresses(env?.to),
          subject: env?.subject || "(no subject)",
          preview: "",
          date: isoDate(msg),
          seen: flags.seen,
          flagged: flags.flagged,
          answered: flags.answered,
          hasAttachments: structureHasAttachments(msg.bodyStructure),
        });
        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
      }

      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
      await Promise.all(
        pageUids.map(async (uid) => {
          const summary = metaByUid.get(uid);
          if (!summary) return;
          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
        }),
      );

      const messages = pageUids
        .map((uid) => metaByUid.get(uid))
        .filter((m): m is MessageSummary => Boolean(m));
      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
    },
    { readOnly: true },
  );
}

// ---------------------------------------------------------------------------
// Single message
// ---------------------------------------------------------------------------

/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
  const { cred } = await resolveMailbox(mailboxAddress);

  return withMailbox(cred, folder, async (client) => {
    const msg = await client.fetchOne(
      String(uid),
      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
      { uid: true },
    );
    if (!msg || !msg.source) throw new Error("Message not found.");

    const parsed = await simpleParser(msg.source);
    const flags = readFlags(msg.flags);
    const env = msg.envelope;

    const attachments = (parsed.attachments || [])
      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
      .map((a, i) => ({
        id: `${uid}:${a.partId ?? String(i + 1)}`,
        filename: a.filename || `attachment-${i + 1}`,
        mime: a.contentType || "application/octet-stream",
        sizeBytes: a.size ?? 0,
      }));

    const full: MessageFull = {
      uid,
      folder,
      from: toMailAddress(env?.from?.[0]),
      to: toMailAddresses(env?.to),
      cc: toMailAddresses(env?.cc),
      subject: env?.subject || parsed.subject || "(no subject)",
      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
      date: isoDate(msg),
      seen: true, // becomes read as a side effect of opening
      flagged: flags.flagged,
      answered: flags.answered,
      hasAttachments: attachments.length > 0,
      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
      text: parsed.text ?? null,
      attachments,
    };

    // Mark read (mailbox opened read-write). Best effort — never fail the read.
    try {
      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
    } catch {
      /* ignore */
    }

    return full;
  });
}

// ---------------------------------------------------------------------------
// Sending
// ---------------------------------------------------------------------------

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Parse a comma/semicolon-separated recipient string into validated addresses. */
function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
  const parts = (input || "")
    .split(/[,;]+/)
    .map((s) => s.trim())
    .filter(Boolean);
  const list: string[] = [];
  const invalid: string[] = [];
  for (const p of parts) {
    // Tolerate "Name <addr>" form by extracting the address.
    const m = p.match(/<([^>]+)>/);
    const addr = (m ? m[1] : p).trim();
    if (EMAIL_RE.test(addr)) list.push(addr);
    else invalid.push(p);
  }
  return { list, invalid };
}

/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
async function findSentPath(client: ImapFlow): Promise<string> {
  try {
    const list = await client.list();
    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
    return sent?.path || "Sent";
  } catch {
    return "Sent";
  }
}

/**
 * Send a message from the user's own mailbox over SMTP submission, append a copy
 * to Sent, and (for replies) thread it + flag the original \Answered.
 */
export async function sendMessage(
  payload: SendPayload,
  mailboxAddress?: string,
): Promise<{ ok: boolean; error?: string }> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });

  const to = parseRecipients(payload.to);
  const cc = parseRecipients(payload.cc);
  const bcc = parseRecipients(payload.bcc);
  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
    return { ok: false, error: "Nothing to send — add a subject or a message." };
  }

  try {
    // Look up threading headers when this is a reply.
    let inReplyTo: string | undefined;
    let references: string | undefined;
    if (payload.inReplyToUid && payload.replyFolder) {
      try {
        await withMailbox(cred, payload.replyFolder, async (client) => {
          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
          if (orig && orig.envelope?.messageId) {
            inReplyTo = orig.envelope.messageId;
            references = orig.envelope.messageId;
          }
          // Mark the message we're replying to as answered (best effort).
          try {
            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
          } catch {
            /* ignore */
          }
        });
      } catch {
        /* original not found — send without threading headers */
      }
    }

    // Compile the message once so the exact bytes are both sent and saved to Sent.
    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
    const built = await composer.sendMail({
      from: cred.address,
      to: to.list,
      cc: cc.list.length ? cc.list : undefined,
      bcc: bcc.list.length ? bcc.list : undefined,
      subject: payload.subject || "",
      text: payload.text || undefined,
      html: payload.html || undefined,
      inReplyTo,
      references,
    });
    const raw = built.message as Buffer;

    const smtp = nodemailer.createTransport({
      host: MAIL_SMTP_HOST,
      port: MAIL_SMTP_PORT,
      secure: MAIL_SMTP_PORT === 465,
      requireTLS: MAIL_SMTP_PORT !== 465,
      tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
      auth: { user: cred.address, pass: cred.password },
    });
    await smtp.sendMail({ envelope: built.envelope, raw });

    // Save a copy to Sent (best effort — the message already went out).
    try {
      await withImap(cred, async (client) => {
        const sentPath = await findSentPath(client);
        await client.append(sentPath, raw, ["\\Seen"]);
      });
    } catch {
      /* Sent append failed — not fatal */
    }

    return { ok: true };
  } catch (e) {
    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
  }
}

// ---------------------------------------------------------------------------
// Flags / move / delete
// ---------------------------------------------------------------------------

/** Set or clear the \Seen or \Flagged flag on a message. */
export async function setFlag(
  folder: string,
  uid: number,
  flag: "seen" | "flagged",
  value: boolean,
  mailboxAddress?: string,
): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
  await withMailbox(cred, folder, async (client) => {
    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
  });
}

/** Move a message from one folder to another. */
export async function moveMessage(
  folder: string,
  uid: number,
  toFolder: string,
  mailboxAddress?: string,
): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
  await withMailbox(cred, folder, async (client) => {
    await client.messageMove(String(uid), toFolder, { uid: true });
  });
}

/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });

  await withImap(cred, async (client) => {
    // Determine the Trash folder path.
    let trashPath = "Trash";
    try {
      const list = await client.list();
      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
      if (trash) trashPath = trash.path;
    } catch {
      /* fall back to "Trash" */
    }

    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
    const lock = await client.getMailboxLock(folder);
    try {
      if (inTrash) {
        await client.messageDelete(String(uid), { uid: true });
      } else {
        await client.messageMove(String(uid), trashPath, { uid: true });
      }
    } finally {
      lock.release();
    }
  });
}

// Reference the imported type so `MailboxCredentials` stays part of the module's
// public surface expectations without an unused-import error.
export type { MailboxCredentials };

