import { resolveMailbox, withImap } from "@/lib/mail/imap";

// GET /api/mail/attachment?folder=&uid=&part=&mailbox=
//
// Streams a single MIME part of one of the caller's own messages. Auth +
// ownership are enforced by `resolveMailbox` (requires a signed-in user and that
// the mailbox belongs to them); the IMAP server itself only exposes that user's
// messages, so there is no cross-account path here.
export async function GET(req: NextRequest) {
  const sp = req.nextUrl.searchParams;
  const folder = sp.get("folder")?.trim();
  const uidRaw = sp.get("uid")?.trim();
  const part = sp.get("part")?.trim();
  const mailbox = sp.get("mailbox")?.trim() || undefined;

  const uid = Number(uidRaw);
  if (!folder || !part || !uidRaw || !Number.isInteger(uid) || uid <= 0) {
    return NextResponse.json({ error: "bad request" }, { status: 400 });
  }

  let cred;
  try {
    ({ cred } = await resolveMailbox(mailbox));
  } catch (e) {
    const msg = String((e as Error)?.message ?? e);
    const status = msg === "UNAUTHORIZED" ? 401 : 403;
    return NextResponse.json({ error: msg }, { status });
  }

  try {
    const result = await withImap(cred, async (client) => {
      const lock = await client.getMailboxLock(folder, { readOnly: true });
      try {
        const many = await client.downloadMany(String(uid), [part], { uid: true });
        return many[part] ?? null;
      } finally {
        lock.release();
      }
    });

    if (!result || !result.content) {
      return NextResponse.json({ error: "not found" }, { status: 404 });
    }

    const contentType = result.meta?.contentType || "application/octet-stream";
    const filename = sanitizeFilename(result.meta?.filename) || `attachment-${part}`;

    return new NextResponse(new Uint8Array(result.content), {
      status: 200,
      headers: {
        "Content-Type": contentType,
        "Content-Disposition": `attachment; filename="${filename}"; filename*=UTF-8''${encodeURIComponent(filename)}`,
        "Content-Length": String(result.content.length),
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "private, no-store",
      },
    });
  } catch (e) {
    return NextResponse.json({ error: String((e as Error)?.message ?? e).slice(0, 200) }, { status: 502 });
  }
}

// Strip path separators, quotes and control chars so the filename can't break
// out of the Content-Disposition header.
function sanitizeFilename(name?: string): string {
  if (!name) return "";
  const cleaned = Array.from(name)
    .filter((ch) => {
      const c = ch.codePointAt(0) ?? 0;
      if (c < 0x20 || c === 0x7f) return false; // control chars
      if (ch === '"' || ch === "\\" || ch === "/") return false;
      return true;
    })
    .join("");
  return cleaned.trim().slice(0, 200);
}

